function pawShape(g,x,y,r,t=0){g.save();g.translate(x,y);const a=g.createRadialGradient(-r*.2,-r*.2,1,0,0,r);a.addColorStop(0,'#fff9ff99');a.addColorStop(1,'#d1b7df25');ellipse(g,0,r*.25,r*.68,r*.57,a);for(let j=0;j<4;j++)ellipse(g,(j-1.5)*r*.4,-r*.5+Math.abs(j-1.5)*r*.17,r*.22,r*.27,a);g.strokeStyle='#f5e3ffcc';g.lineWidth=2;g.beginPath();g.ellipse(0,r*.25,r*.68,r*.57,0,0,7);g.stroke();g.restore();}
function barrierPlane(g,x,y,w,h,t){g.save();g.translate(x,y);const a=g.createLinearGradient(-w,-h,w,h);a.addColorStop(0,'#e1fffa55');a.addColorStop(.5,'#73edb019');a.addColorStop(1,'#8ff5df55');poly(g,[[-w*.7,-h],[w*.65,-h*.88],[w,h],[-w*.9,h*.88]],a);line(g,[[-w*.7,-h],[w*.65,-h*.88],[w,h],[-w*.9,h*.88],[-w*.7,-h]],'#b1ffe5',2);for(let j=0;j<5;j++)line(g,[[-w*.7+j*w*.3,-h*.9],[-w*.9+j*w*.36,h*.83]],'#bdfbe622',1);line(g,[[-w*.4,-h*.72],[w*.38,h*.65]],'#f0ffef99',3);g.restore();}
function phoenixWings(g,x,y,t,scale=1){g.save();g.translate(x,y);g.scale(scale,scale);g.globalCompositeOperation='screen';for(const dir of [-1,1])for(let j=0;j<7;j++){const a=j*.15-.7+Math.sin(t*7)*.12,reach=105-j*6;g.save();g.scale(dir,1);g.rotate(a);const grad=g.createLinearGradient(0,0,reach,0);grad.addColorStop(0,'#027ca633');grad.addColorStop(.65,'#21cfeca0');grad.addColorStop(1,'#cafffa');poly(g,[[0,0],[reach,-14],[reach-20,3],[25,12]],grad);line(g,[[15,0],[reach-7,-8]],'#8cf7ff',1.5);g.restore();}g.restore();}
function phoenixFlame(g,x,y,dir,time,phase){g.save();g.translate(x,y);g.scale(dir,1);g.globalCompositeOperation='screen';const flap=Math.sin(time*.34)*18,glow=g.createRadialGradient(0,0,4,0,0,95);glow.addColorStop(0,'#ecfffa');glow.addColorStop(.25,'#51efffbd');glow.addColorStop(1,'#0875af00');ellipse(g,0,0,95,78,glow);for(const side of [-1,1])for(let j=0;j<8;j++){const wingY=side*(20+j*7+flap*(j/8)),reach=55+j*8;const a=g.createLinearGradient(0,0,-reach,wingY);a.addColorStop(0,'#d9ffef');a.addColorStop(.45,'#25e6eacc');a.addColorStop(1,'#116dff00');poly(g,[[8,0],[-reach,wingY],[-reach+20,wingY+side*10],[-12,side*12]],a);}poly(g,[[-30,10],[12,-20],[34,-22],[45,-10],[25,-5],[10,22]],'#adfff4');poly(g,[[34,-22],[52,-16],[40,-10]],'#fff1a8');ellipse(g,33,-17,2,2,'#004c78');for(let j=0;j<25;j++){const z=(time*.07+j*.41)%1,xx=-30-z*145,yy=Math.sin(j*3.7+time*.12)*(8+z*40);ellipse(g,xx,yy,2+(1-z)*5,4+(1-z)*13,j%3?'#38e9f5aa':'#eaffcecc',Math.sin(time*.1+j)*.4);}g.restore();}
