 if(id==='brook'&&['heavy','special','ult'].includes(s.key)&&(wind||active)){g.save();g.globalAlpha=.35;for(let j=0;j<14;j++){const xx=f.x+Math.sin(j*2.4+m.frame*.015)*(40+j*4),yy=f.y-20-j*10;line(g,[[xx,yy],[xx+Math.sin(j+m.frame*.03)*20,yy-15]],'#c9fcff',2);}g.restore();g.globalAlpha=wind?charge*.4:.5;for(let j=0;j<6;j++)ellipse(g,f.x+Math.sin(j*2+m.frame*.025)*45,y-15-j*12,32,8,'#b6efff55');if(s.key==='ult')spirit(g,f.x-f.dir*50,y-115,charge);}
